a<-commandArgs(TRUE)[1];t<-readRDS(file.path(a,"target_fit_details.private.rds"));rows<-list();for(v in c("g0","g1","g2")){b<-t[[paste(v,"01","Firth",sep="_")]];n<-names(b$coef);V<-b$var;contrast<-function(g,gs){L<-rep(0,length(n));L[match(c("g","gs"),n)]<-c(g,gs);est<-sum(L*b$coef);se<-sqrt(drop(t(L)%*%V%*%L));c(beta=est,se=se,OR=exp(est),lo=exp(est-1.96*se),hi=exp(est+1.96*se),p=pchisq((est/se)^2,1,lower.tail=FALSE))};for(label in c("female_per_allele","male_carrier","constraint_01","constraint_02")){C<-switch(label,female_per_allele=c(1,0),male_carrier=c(1,1),constraint_01=c(0,1),constraint_02=c(-1,1));rows[[paste(v,label)]]<-data.frame(target=v,contrast=label,t(contrast(C[1],C[2])))} };out<-do.call(rbind,rows);write.csv(out,file.path(a,"sex_effects_and_constraints_Wald.csv"),row.names=FALSE);print(out[,c("target","contrast","OR","lo","hi","p")],row.names=FALSE)
